/* Learn by moving one continuous cube. Demonstrations are optional previews. */
const LessonFlow=(()=>{
const VERSION='cube-consistent-v2',TITLES=['흰 꽃','흰 십자','1층 코너','2층 엣지','노란 십자','노란 면','코너 자리','엣지 자리'];
const E=[[5,10],[7,19],[3,37],[1,46],[32,16],[28,25],[30,43],[34,52],[23,12],[21,41],[50,39],[48,14]],C=[[8,9,20],[6,18,38],[0,36,47],[2,45,11],[29,26,15],[27,44,24],[33,53,42],[35,17,51]],EC=['UR','UF','UL','UB','DR','DF','DL','DB','FR','FL','BL','BR'],CC=['URF','UFL','ULB','UBR','DFR','DLF','DBL','DRB'];
let state=null,model=null,view='auto',job=null,moving=false,loading='',error='',menu=false,chosenFace=null,preview=false,demoPos=0,demoToken=0,demoStopRequested=false,browseIndex=null,browsePlan=null,browseJob=null,browseLoading=false,browseError='';
function read(mode){try{let o=JSON.parse(localStorage.getItem(VERSION+'-'+mode)||'null');return o&&o.mode===mode&&o.current?.length===54?o:null;}catch{return null;}}
function migrate(o){if(o.flowVersion===3)return o;const actual=([4,5].includes(o.phase)||o.phase===3&&o.resumePractice)?o.practice||o.current:o.current;return{...o,flowVersion:3,current:o.current,baseline:o.current,practice:actual,plan:o.plan||null,history:o.history||[],completed:o.completed||[],revision:o.revision||0,stageReady:o.stage<8&&!!o.plan&&milestone(Cube.fromString(actual),o.stage),feedback:''};}

try{let m=localStorage.getItem(VERSION+'-mode');state=read(m==='camera'?'camera':'sample');}catch{}
function save(){if(!state)return;try{localStorage.setItem(VERSION+'-'+state.mode,JSON.stringify(state));localStorage.setItem(VERSION+'-mode',state.mode);}catch{}}
const lower=c=>fixedEdges(c,[4,5,6,7,8,9,10,11])&&fixedCorners(c,[4,5,6,7]);
function fresh(mode,str,start){const c=valid(str);return{flowVersion:3,mode,initial:str,current:str,baseline:str,practice:str,initiallySolved:c.isSolved(),stage:start??detect(c),plan:null,history:[],feedback:'',completed:[],revision:0,stageReady:false};}
function routeToLesson(){if(location.hash==='#learn')render();else location.hash='#learn';}
function restore(){cancelBrowse();demoToken++;preview=false;moving=false;if(job){job.terminate();job=null;}loading='';error='';view='auto';if(state){state=migrate(state);model=Cube.fromString(state.practice||state.current);save();if(state.stage<8&&!state.plan)prepare();}}
function prepare(){if(!state||state.stage>=8||state.stageReady)return;const origin=state.practice||state.current,revision=++state.revision;loading='다음 조각을 찾고 있어요…';error='';job=new Worker('worker.js?v=standard-colors-2');const timeout=setTimeout(()=>{if(!job)return;job.terminate();job=null;loading='';error='현재 큐브는 저장했어요. 다시 준비해주세요.';render();},45000);job.onmessage=e=>{if(e.data.type==='progress')return;if(!state||state.revision!==revision)return;clearTimeout(timeout);job.terminate();job=null;loading='';if(e.data.type==='error'){error=e.data.message;render();return;}state.plan=e.data.stages;state.current=origin;state.baseline=origin;state.practice=origin;state.history=[];while(state.stage<8&&!state.plan[state.stage].moves.length){state.completed.push(state.stage);state.stage++;}model=Cube.fromString(origin);save();if(route==='learn')render();};job.onerror=()=>{clearTimeout(timeout);job?.terminate();job=null;loading='';error='현재 큐브는 저장했어요. 다시 준비해주세요.';render();};job.postMessage({facelets:origin,startStage:state.stage});}
function shell(title,sub,content){return header()+heading('보고, 직접 돌리며 배우는 큐브',title,sub)+content;}
function fixedEdges(c,ids){return ids.every(i=>c.ep[i]===i&&c.eo[i]===0);}
function fixedCorners(c,ids){return ids.every(i=>c.cp[i]===i&&c.co[i]===0);}
function milestone(c,n){if(n===0)return[4,5,6,7].every(p=>{let i=c.ep.indexOf(p);return i<4&&c.eo[i]===0;});if(n===1)return fixedEdges(c,[4,5,6,7]);if(n===2)return milestone(c,1)&&fixedCorners(c,[4,5,6,7]);if(n===3)return lower(c);if(n===4)return lower(c)&&c.eo.slice(0,4).every(v=>v===0);if(n===5)return milestone(c,4)&&c.co.slice(0,4).every(v=>v===0);if(n===6)return milestone(c,5)&&c.cp.every((p,i)=>p===i);return c.isSolved();}
function detect(c){if(c.isSolved())return 8;for(let n=6;n>=1;n--)if(milestone(c,n))return n+1;return milestone(c,0)?1:0;}
function openExample(start){save();let existing=read('sample');if(start===undefined&&existing){state=existing;restore();routeToLesson();return;}let str=new Cube().move("R U R' U' F U F' U' L'").asString();if(start===1)str=new Cube().move("F2 R2 B2 L2 U'").asString();state=fresh('sample',str,start??0);restore();routeToLesson();}
function openCaptured(str){try{valid(str);}catch(e){scanError=e.message;render();return;}save();state=fresh('camera',str);restore();routeToLesson();}
function switchMode(mode){if(moving||loading||state?.mode===mode)return;save();let other=read(mode);if(other){state=other;restore();render();}else if(mode==='sample')openExample();else location.hash='#scan';}
function stage(){return state.plan[state.stage];}
function segment(){return stage().segments[0];}
function moves(){const seg=segment();return stage().moves.slice(seg.start,seg.end);}
function descriptor(){const seg=segment();if(seg.piece!=null)return{piece:seg.piece,kind:seg.kind};return{kind:[5,6].includes(state.stage)?'corner':'edge',piece:null};}
function targetColors(){const d=descriptor();return d.piece==null?'노란색 조각들':(d.kind==='corner'?CC:EC)[d.piece].split('').map(f=>NAMES[f]).join('·');}
function basisFace(){if(state.stage===0||state.stage>=4)return'U';const d=descriptor(),cs=(d.kind==='corner'?CC:EC)[d.piece];if(state.stage===2)return'D';return[...cs].find(f=>f!=='D'&&f!=='U')||'F';}
function targetIndices(c=model){const d=descriptor();if(d.piece!=null)return(d.kind==='corner'?C:E)[(d.kind==='corner'?c.cp:c.ep).indexOf(d.piece)];return(d.kind==='corner'?C:E).slice(0,4).flat();}
function destination(){const d=descriptor();if(state.stage===0){const end=Cube.fromString(segment().final);return E[end.ep.indexOf(d.piece)];}if(state.stage===1)return E[d.piece-4];if(d.piece!=null)return(d.kind==='corner'?C:E)[d.piece];return(d.kind==='corner'?C:E).slice(0,4).flat();}
function segmentGoal(c,n,d,initial){if(n===0){const isPetal=(x,p)=>{let i=x.ep.indexOf(p);return i<4&&x.eo[i]===0;};return isPetal(c,d.piece)&&[4,5,6,7].filter(p=>isPetal(initial,p)).every(p=>isPetal(c,p));}if(n===1){const fixed=[4,5,6,7].filter(i=>initial.ep[i]===i&&initial.eo[i]===0);const locked=[d.piece,...fixed],remaining=[4,5,6,7].filter(p=>!locked.includes(p));return fixedEdges(c,locked)&&remaining.every(p=>{const i=c.ep.indexOf(p);return i<4&&c.eo[i]===0;});}if(n===2){const fixed=[4,5,6,7].filter(i=>initial.cp[i]===i&&initial.co[i]===0);return milestone(c,1)&&fixedCorners(c,[d.piece,...fixed]);}if(n===3){const fixed=[8,9,10,11].filter(i=>initial.ep[i]===i&&initial.eo[i]===0);return milestone(c,2)&&fixedEdges(c,[d.piece,...fixed]);}return milestone(c,n);}
function practiceGoal(c){return segmentGoal(c,state.stage,descriptor(),Cube.fromString(state.current));}
function header(){return`<div class="source-bar"><div class="source-choices"><button data-source="sample" aria-pressed="${state?.mode==='sample'}">예제 큐브</button><button data-source="camera" aria-pressed="${state?.mode==='camera'}">내 촬영 큐브</button></div><div class="source-status"><b>${state?.mode==='camera'?'내가 촬영한 상태를 이어가는 중':state?'준비된 예제로 배우는 중':'학습할 큐브를 선택해주세요'}</b>${state?'<button class="text-btn" id="source-state">출발한 6면 보기</button>':''}</div></div>`;}
function chooser(){return shell('어떤 큐브로 배워볼까요?','수업 순서는 같고, 출발하는 큐브와 진도만 달라요.',`<div class="source-cards"><section class="panel"><span class="kicker">예제 큐브</span><h2>준비된 배치로 원리부터</h2><p class="muted">처음 잡는 법부터 흰·주황 엣지 하나를 꽃잎으로 올려요. 다음 색도 같은 방식으로 반복합니다.</p><button class="primary orange" id="choose-example">예제로 첫 수업 시작 →</button></section><section class="panel"><span class="kicker">내 촬영 큐브</span><h2>지금 손에 든 상태 그대로</h2><p class="muted">6면을 등록한 배치에서 시작합니다. 맞춘 부분은 유지하고, 내가 돌린 결과에서 다음 수업을 이어가요.</p><a class="primary" href="#scan">내 큐브 6면 등록 →</a></section></div>`);}
function focusBoard(){document.querySelector('.first-board')?.scrollIntoView({block:'start',behavior:'auto'});}
function colorsOf(c,indices){return[...new Set(indices.map(i=>NAMES[c.asString()[i]]))].join('·');}
function cameraForFace(f){const down=f.endsWith('-low');f=f.replace('-low','');return f==='U'?'rotateX(-75deg) rotateY(0deg)':f==='D'?'rotateX(75deg) rotateY(0deg)':`rotateX(${down?24:-24}deg) rotateY(${{F:-25,R:-115,L:65,B:155}[f]}deg)`;}
function viewButtons(){return`<div class="flow-views">${[['auto','중점 보기'],['F','앞'],['R','오른쪽'],['L','왼쪽'],['B','뒤'],['U','위'],['D','아래']].map(([f,t])=>`<button data-flow-view="${f}">${t}</button>`).join('')}</div>`;}
function lessonGoal(){if(state.stage===0)return`${targetColors()} 엣지의 흰색을 노란 중심 옆에 올려 꽃잎으로 만들어요. 옆 색은 아직 중심과 맞추지 않아도 돼요.`;if(state.stage===1)return`윗면을 돌려 ${targetColors()}의 옆 색을 ${NAMES[basisFace()]} 중심 위에 맞춰요. 그다음 ${NAMES[basisFace()]} 면을 반 바퀴 내려 흰 중심과 연결해요.`;if(state.stage===2)return`${targetColors()} 코너를 같은 세 색의 중심이 만나는 자리에 넣어요. 이미 맞춘 흰 십자도 지켜요.`;if(state.stage===3)return`${targetColors()} 엣지를 두 중심 사이에 넣고, 아래 1층을 복구해요.`;return stage().principle;}
function drawArrow(el,m){const f=m[0],tr={F:'translateZ(80px)',R:'rotateY(90deg) translateZ(80px)',L:'rotateY(-90deg) translateZ(80px)',B:'rotateY(180deg) translateZ(80px)',U:'rotateX(90deg) translateZ(80px)',D:'rotateX(-90deg) translateZ(80px)'}[f];el.insertAdjacentHTML('beforeend',`<div class="face-rotation" style="transform:${tr}" aria-hidden="true" data-move="${m}"><svg viewBox="0 0 100 100" style="${m.includes("'")?'transform:scaleX(-1)':''}"><path d="M26 22 A37 37 0 1 1 15 57" fill="none" stroke="#f6863f" stroke-width="6" stroke-linecap="round"/><path d="M6 63 L13 43 L27 59" fill="#f6863f"/>${m.includes('2')?'<text x="32" y="55" fill="#fff5cf" font-size="16" font-weight="bold">180°</text>':''}</svg></div>`);}
function sourceModal(){modal(`<h2>${state.mode==='camera'?'내가 촬영한 출발 상태':'이 예제의 출발 상태'}</h2><p>드래그해서 여섯 면을 확인하세요. 이 출발 상태는 따로 보관하고, 수업은 직접 적용한 결과에서 계속 이어집니다.</p><div class="source-cube-3d">${cubeHTML(state.initial,'source-cube')}</div>`);}
function autoFace(){if(state.stage===1)return{R:'F',F:'F',L:'L',B:'R'}[basisFace()]||'F';const d=descriptor();if(d.piece!=null){const pos=(d.kind==='corner'?model.cp:model.ep).indexOf(d.piece),face=d.kind==='corner'?['F','L','B','R','F','L','B','R'][pos]:['R','F','L','B','R','F','L','B','F','L','B','R'][pos];return face==='R'?'F':face==='B'?'R':face;}return'F';}
function count(){if(state.stage===0)return[4,5,6,7].filter(p=>{let i=model.ep.indexOf(p);return i<4&&model.eo[i]===0;}).length;if(state.stage===1)return[4,5,6,7].filter(p=>model.ep[p]===p&&model.eo[p]===0).length;if(state.stage===2)return[4,5,6,7].filter(p=>model.cp[p]===p&&model.co[p]===0).length;if(state.stage===3)return[8,9,10,11].filter(p=>model.ep[p]===p&&model.eo[p]===0).length;return null;}
function cue(){if(preview){const m=moves()[demoPos];if(!m)return'시범이 끝났어요. 직접 돌리던 상태로 돌아갑니다.';if(state.stage===1)return m[0]==='U'?`윗면을 돌려 ${targetColors()}의 옆 색을 ${NAMES[basisFace()]} 중심 위에 맞춰요.`:`옆 색이 중심과 맞았어요. ${NAMES[m[0]]} 면을 반 바퀴 내려 흰 중심과 연결해요.`;return `${describe(m).short}. ${segment().why||'표시된 조각의 두 색이 함께 이동하는 모습을 따라가세요.'}`;}if(state.stageReady)return state.stage===0?'흰 꽃이 완성됐어요. 다음에는 꽃잎의 옆 색을 중심에 맞춘 뒤 아래로 내려 흰 십자를 만들어요.':`${TITLES[state.stage]} 완성! 여러 면을 둘러보며 맞춘 조각이 중심색과 연결됐는지 확인해보세요.`;if(state.feedback)return state.feedback;return state.stage===0?`${count()===0?"노랑 위·초록 앞으로 잡아요. ":""}${targetColors()} 조각의 흰색을 노란 중심 옆으로 올려보세요. 두 색은 한 조각으로 함께 움직여요. 이미 올라온 흰 꽃잎은 지켜요.`:lessonGoal();}
function coach(){return`<div class="cube-coach intro-coach" role="status" aria-live="polite"><span class="coach-avatar">✳</span><div><small>${preview?'시범 · '+(demoPos+1)+' / '+moves().length+'수':state.stageReady?'목표 완성':TITLES[state.stage]+' · 직접 해보기'}</small><b>${preview?describe(moves()[demoPos]||moves().at(-1)).short:state.stageReady?'만든 모양을 확인해요':targetColors()+' 조각을 움직여요'}</b><p>${cue()}</p>${!state.stageReady?`<button class="coach-demo" id="flow-inline-demo">${preview?"직접 하기":"▷ 시범 보기"}</button>`:""}</div></div>`;}
function board(){return`<div class="lesson-stage with-coach intro-stage flow-stage">${coach()}<div class="intro-cube-slot">${cubeHTML(model.asString(),'flow-cube')}</div><span class="stage-caption">드래그로 둘러보기 · 층을 돌릴 때는 아래 버튼</span></div>`;}
function practiceControls(){let faces=menu?FACES:[...new Set([...moves().map(m=>m[0]),basisFace()])];const mobileFace=faces.includes(chosenFace)?chosenFace:faces[0];const buttons=f=>['',"'",'2'].map(s=>`<button data-flow-turn="${f+s}">${s==="'"?'↶ 왼쪽 90°':s==='2'?'반 바퀴 180°':'↷ 오른쪽 90°'}</button>`).join('');return`<div class="flow-turns" id="flow-desktop">${faces.map(f=>`<div><b><i style="background:${COLORS[f]}"></i>${NAMES[f]} 중심 면</b><div>${buttons(f)}</div></div>`).join('')}</div><div class="flow-mobile-dock"><div class="flow-face-picks">${faces.map(f=>`<button data-flow-face="${f}" class="${f===mobileFace?'selected':''}"><i style="background:${COLORS[f]}"></i>${NAMES[f]} 면</button>`).join('')}<button id="flow-mobile-undo" aria-label="한 수 되돌리기" ${!state.history.length?"disabled":""}>↶ 되돌리기</button></div><div class="flow-mobile-moves">${buttons(mobileFace)}</div></div><p class="turn-caption">선택한 색의 중심을 정면에서 볼 때의 회전 방향이에요.${state.mode==='camera'?' 손의 큐브도 같은 방향으로 돌려주세요.':''}</p><div class="intro-tools"><button class="text-btn" id="flow-undo" ${!state.history.length?'disabled':''}>↶ 한 수 되돌리기</button><button class="text-btn" id="flow-more">${menu?'필요한 면만':'모든 면 조작'}</button></div>`;}
function principle(){return state.stage===0?'가운데 칸은 면의 이름을 정하는 중심이에요. 두 색이 붙은 변 조각(엣지)은 한 몸으로 움직여요. 노란 중심 주위에 흰 엣지 네 개가 모이면 꽃이에요. 옆 색 정렬은 다음 십자에서 합니다.':state.stage===1?'흰색만 아래로 보내면 십자가 완성되지 않아요. 먼저 윗면을 돌려 옆 색을 같은 색 중심 위에 맞추세요. 그 면을 반 바퀴 돌리면 흰색과 옆 색이 각각 자기 중심에 연결돼요.':stage().principle;}
function cancelBrowse(){browseJob?.terminate();browseJob=null;browseIndex=null;browsePlan=null;browseLoading=false;browseError='';}
function lessonArrows(index=state.stage,caption=''){return`<div class="lesson-step-nav" aria-label="수업 앞뒤로 이동"><button id="lesson-prev" aria-label="이전 수업" ${index<=0?'disabled':''}>‹</button><div>${caption||`${index+1} / 8 · ${TITLES[index]}`}<small>${browseIndex!==null?'수업 미리보기 · 연습 진도는 보관 중':''}</small></div><button id="lesson-next" aria-label="다음 수업" ${index>=7&&!(browseIndex===null&&state.stage===7&&state.stageReady)?'disabled':''}>›</button></div>`;}
function goLesson(index){if(moving||busy||loading||index<0||index>8)return;if(index===state.stage){browseIndex=null;render();return;}if(index===state.stage+1&&state.stageReady&&browseIndex===null){nextStage();return;}if(index>=8)return;save();browseIndex=index;if(browsePlan){render();return;}if(browseJob){render();return;}browseLoading=true;browseError='';const initial=state.initial,mode=state.mode;const worker=new Worker('worker.js?v=standard-colors-2');browseJob=worker;const timeout=setTimeout(()=>{if(browseJob!==worker)return;worker.terminate();browseJob=null;browseLoading=false;browseError='미리보기를 준비하지 못했어요. 내 연습으로 돌아가서 다시 시도해주세요.';render();},45000);worker.onmessage=e=>{if(e.data.type==='progress')return;if(browseJob!==worker)return;clearTimeout(timeout);worker.terminate();browseJob=null;browseLoading=false;if(!state||state.initial!==initial||state.mode!==mode)return;if(e.data.type==='error')browseError=e.data.message;else browsePlan=e.data.stages;if(route==='learn')render();};worker.onerror=()=>{clearTimeout(timeout);worker.terminate();if(browseJob!==worker)return;browseJob=null;browseLoading=false;browseError='미리보기를 준비하지 못했어요. 내 연습 상태는 그대로 보관돼요.';render();};worker.postMessage({facelets:initial,startStage:0});render();}
function browsePage(){const n=browseIndex,s=browsePlan?.[n];return shell(`${n+1}. ${TITLES[n]} 만들기`,'수업 내용을 앞뒤로 살펴보세요. 직접 돌리던 큐브는 그대로 보관돼요.',`<section class="panel first-board hands-on lesson-preview">${lessonArrows(n)}<div class="lesson-stage with-coach intro-stage flow-stage"><div class="cube-coach intro-coach"><span class="coach-avatar">✳</span><div><small>수업 미리보기</small><b>${TITLES[n]}의 목표</b><p>${browseError||s?.principle||'출발 큐브에서 수업 배치를 준비하고 있어요…'}</p></div></div><div class="intro-cube-slot">${s?cubeHTML(s.initial,'lesson-preview-cube'):'<div class="loading" role="status">준비 중…</div>'}</div><span class="stage-caption">출발 상태를 바탕으로 한 수업 배치 · 드래그로 둘러보기</span></div><button class="primary orange lesson-resume" id="lesson-resume">직접 돌리던 연습으로 돌아가기</button></section>`);}
function page(){if(!state)return chooser();if(browseIndex!==null)return browsePage();if(error)return shell('현재 큐브는 그대로 보관했어요.','',`<div class="panel"><p class="error">${error}</p><button id="flow-retry" class="primary">다시 준비</button><button id="flow-restore-piece" class="secondary">이번 조각 시작으로 되돌리기</button></div>`);if(state.stage>=8)return shell('여섯 면을 완성했어요.','같은 큐브를 꽃부터 한 층씩 이어서 맞췄어요.',`<div class="panel first-board">${lessonArrows(8,'완성')}${cubeHTML(model.asString(),'completed-cube')}<button class="primary orange" id="flow-new-example">예제로 다시 연습</button><a class="secondary" href="#scan">새 큐브 촬영</a></div>`);if(loading||!state.plan)return shell('현재 큐브에서 이어갑니다.','',`<div class="panel loading" role="status">${loading||'수업 준비 중…'}</div>`);const n=count();return shell(`${state.stage+1}. ${TITLES[state.stage]} 만들기`,state.stage===0?'노랑 위 · 초록 앞. 먼저 흰 꽃잎 네 개를 모아봐요.':state.stage===1?'꽃잎의 옆 색을 맞추고, 흰 중심 쪽으로 내려요.':'맞춘 부분을 지키면서 다음 조각을 넣어봐요.',`<div class="consistent-curriculum">${TITLES.map((t,i)=>`<span class="${i===state.stage?'current':i<state.stage?'finished':''}">${i<state.stage?'✓':i+1} ${t}</span>`).join('')}</div><section class="panel first-board hands-on">${lessonArrows(state.stage)}<div class="lesson-task"><b>${state.stageReady?'✓ '+TITLES[state.stage]+' 완성':targetColors()+' '+(descriptor().kind==='corner'?'코너':'엣지')}</b><span>${n===null?'맞춘 부분을 지켜요':n+' / 4개'}</span></div><div class="lesson-workspace">${board()}<aside class="lesson-tools"><div class="lesson-actions">${preview?'<button class="primary" id="flow-stop-demo">시범 끝내고 직접 하기</button><span>이번 조각의 시작 상태로 보여주는 시범이에요. 직접 돌리던 큐브는 보관 중입니다.</span>':state.stageReady?`<button class="primary orange" id="flow-next-stage">${state.stage===7?'완성 확인':TITLES[state.stage+1]+' 만들기로 →'}</button>`:'<button class="secondary" id="flow-demo">▷ 이 조각 시범 보기</button><span>막히면 시범을 보고, 직접 같은 자리에 보내보세요.</span>'}</div>${!preview&&!state.stageReady?practiceControls():''}<details class="lesson-principle"><summary>왜 이렇게 움직이나요?</summary><p>${principle()}</p><p>◎는 옮길 조각, ‘자리’는 목적지예요. 중심색을 보면 조각이 들어갈 면을 찾을 수 있어요.</p></details></aside></div></section>`);}
function decorate(){const el=document.getElementById('flow-cube');if(!el)return;el.style.transform=cameraForFace(view==='auto'?autoFace():view);const targets=targetIndices(),dest=destination();[...el.querySelectorAll('.sticker')].forEach((t,i)=>{const f=FACES[Math.floor(i/9)],e=E.find(a=>a.includes(i)),c=C.find(a=>a.includes(i)),ids=e||c||[i];t.setAttribute('aria-label',i%9===4?NAMES[f]+' 중심':colorsOf(model,ids)+' '+(e?'엣지':c?'코너':'중심'));t.setAttribute('role','button');t.setAttribute('tabindex','0');if(!state.stageReady&&targets.includes(i)){t.classList.add('first-target');t.innerHTML='<span>◎</span>';}if(!state.stageReady&&dest.includes(i)&&!targets.includes(i)){t.classList.add('flow-destination');t.innerHTML='<span>자리</span>';}t.onclick=()=>choose(i);t.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();choose(i);}};});if(preview&&moves()[demoPos])drawArrow(el,moves()[demoPos]);}
function choose(i){if(moving||preview||state.stageReady)return;const f=FACES[Math.floor(i/9)],edge=E.find(a=>a.includes(i)),corner=C.find(a=>a.includes(i));state.feedback=i%9===4?`${NAMES[f]} 중심이에요. 이 중심을 가진 면의 조각들이 함께 회전해요.`:`${colorsOf(model,edge||corner||[i])} ${edge?'엣지':'코너'}예요. ${targetIndices().includes(i)?'지금 옮길 조각이에요. 목적지까지 따라가보세요.':'이 색들은 한 조각으로 함께 움직여요.'}`;save();render();}
function acceptResult(){if(!practiceGoal(model))return false;state.current=model.asString();state.practice=state.current;state.history=[];state.feedback=`좋아요! ${targetColors()} 조각이 제자리에 왔어요. 다음 조각도 같은 원리로 옮겨봐요.`;if(milestone(model,state.stage)){state.stageReady=true;if(!state.completed.includes(state.stage))state.completed.push(state.stage);save();return true;}state.plan=null;save();prepare();return true;}
function moveFeedback(m,before){const d=descriptor();if(state.stage===1){const p=model.ep.indexOf(d.piece);if(p===d.piece-4&&model.eo[p]===0)return`옆 색이 ${NAMES[basisFace()]} 중심 바로 위에 맞았어요. 이제 ${NAMES[basisFace()]} 면을 반 바퀴 돌려 흰 중심 쪽으로 내려보세요.`;return m[0]==='U'?`흰 꽃잎은 위에 남아 있어요. ${targetColors()}의 옆 색과 ${NAMES[basisFace()]} 중심이 나란히 연결되는지 보세요.`:'옆 색이 그 면의 중심과 연결됐나요? 다르면 한 수 되돌리고 윗면에서 옆 색부터 맞춰보세요.';}if(state.stage===0){const old=Cube.fromString(before);if(old.ep.indexOf(d.piece)===model.ep.indexOf(d.piece))return'목표 조각은 그대로 있고, 다른 조각들이 움직였어요. 위의 빈자리를 준비하면 이미 만든 꽃잎을 밀어내지 않고 새 꽃잎을 올릴 수 있어요.';const i=targetIndices().find(i=>model.asString()[i]==='D'),face=FACES[Math.floor(i/9)];return`두 색이 함께 움직여 흰색이 지금 ${NAMES[face]} 중심 면 쪽을 향해요. 흰색이 위로 가도록 옮기되, 이미 올린 꽃잎은 위에 남겨요.`;}return'목표 조각이 목적지에 왔는지 살펴보세요. 이미 맞춘 부분도 함께 지켜요.';}
async function act(m){if(moving||busy||preview||state.stageReady)return;moving=true;const before=model.asString();await turn(model,m,'flow-cube');state.history.push({before,move:m});state.practice=model.asString();state.feedback='';moving=false;if(!acceptResult()){state.feedback=moveFeedback(m,before);save();}render();}

function stopDemo(){demoToken++;preview=false;moving=false;model=Cube.fromString(state.practice||state.current);view=state.practiceView||'auto';render();}
async function demo(){if(moving||busy||preview)return;const token=++demoToken;demoStopRequested=false;state.practice=model.asString();state.practiceView=view;save();preview=true;model=Cube.fromString(state.current);view=autoFace();const sequence=moves();for(demoPos=0;demoPos<sequence.length;demoPos++){if(token!==demoToken)return;render();moving=true;await new Promise(r=>setTimeout(r,450));if(token!==demoToken)return;await turn(model,sequence[demoPos],'flow-cube');moving=false;if(token!==demoToken)return;if(demoStopRequested){stopDemo();return;}}await new Promise(r=>setTimeout(r,800));if(token===demoToken)stopDemo();}
function nextStage(){if(moving||!state.stageReady)return;state.stage++;state.stageReady=false;state.plan=null;state.feedback='';save();prepare();render();}
function undo(){if(moving||preview||!state.history.length)return;model=Cube.fromString(state.history.pop().before);state.practice=model.asString();state.feedback='한 수 전으로 돌아왔어요. 조각이 어디로 이동하는지 다시 살펴보세요.';save();render();}
function bind(){document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>switchMode(b.dataset.source));const on=(id,fn)=>{const b=document.getElementById(id);if(b)b.onclick=fn;};on('choose-example',()=>openExample());on('source-state',sourceModal);on('flow-retry',()=>{prepare();render();});on('flow-restore-piece',()=>{state.practice=state.current;state.plan=null;state.history=[];prepare();render();});on('flow-new-example',()=>openExample(0));if(state){const shown=browseIndex??state.stage;on('lesson-prev',()=>goLesson(shown-1));on('lesson-next',()=>goLesson(shown+1));on('lesson-resume',()=>{if(moving)return;browseIndex=null;render();});}if(browseIndex!==null||!state||loading||error||state.stage>=8||!state.plan)return;decorate();document.querySelectorAll('[data-flow-view]').forEach(b=>b.onclick=()=>{if(moving||preview)return;view=b.dataset.flowView;render();});document.querySelectorAll('[data-flow-face]').forEach(b=>b.onclick=()=>{if(moving)return;chosenFace=b.dataset.flowFace;render();});document.querySelectorAll('[data-flow-turn]').forEach(b=>b.onclick=()=>act(b.dataset.flowTurn));on('flow-demo',demo);on('flow-inline-demo',()=>{if(!preview){demo();return;}if(moving){demoStopRequested=true;return;}stopDemo();});on('flow-stop-demo',()=>{if(moving){demoStopRequested=true;return;}stopDemo();});on('flow-next-stage',nextStage);on('flow-undo',undo);on('flow-mobile-undo',undo);on('flow-more',()=>{if(moving)return;menu=!menu;render();});}
if(state)restore();
return{clear:()=>{cancelBrowse();demoToken++;if(job)job.terminate();job=null;state=null;model=null;loading='';error='';},page,bind,position:()=>window.scrollTo(0,0),openExample,openCaptured,switchMode,start:()=>{if(!state)openExample();else{restore();routeToLesson();}},tests:{milestone,detect,read,segmentGoal,migrate}};
})();
